package com.way2jobs.scraper;
import com.way2jobs.entity.*; import com.way2jobs.notification.entity.Notification; import com.way2jobs.notification.repository.NotificationRepository; import com.way2jobs.repository.JobRepository; import com.way2jobs.scraper.model.ScrapedJob; import com.way2jobs.service.JobService; import lombok.RequiredArgsConstructor; import org.springframework.dao.DataIntegrityViolationException; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import java.time.LocalDate;
@Service @RequiredArgsConstructor public class ScraperPersistenceService {private final JobRepository jobs;private final JobService jobService;private final NotificationRepository notifications; public sealed interface PersistOutcome permits Imported,Duplicate,Failed{} public record Imported(Long jobId)implements PersistOutcome{} public record Duplicate()implements PersistOutcome{} public record Failed(String reason)implements PersistOutcome{} @Transactional(propagation=Propagation.REQUIRES_NEW) public PersistOutcome persistOne(ScrapedJob s,Department d,Category c,State st){try{LocalDate date=s.getLastDateRaw()==null?null:LocalDate.parse(s.getLastDateRaw());if(jobs.existsByNotificationUrlIgnoreCase(s.getNotificationUrl())||jobs.existsByApplyUrlIgnoreCase(s.getApplyUrl())||jobs.existsByTitleIgnoreCaseAndLocationIgnoreCaseAndLastDateAndDepartmentIdAndCategoryIdAndStateId(s.getTitle(),s.getLocation(),date,d.getId(),c.getId(),st.getId()))return new Duplicate();Job j=jobService.saveJob(Job.builder().title(s.getTitle()).qualification(s.getQualification()).vacancies(s.getVacanciesRaw()==null?null:Integer.valueOf(s.getVacanciesRaw())).salary(s.getSalary()).location(s.getLocation()).lastDate(date).notificationUrl(s.getNotificationUrl()).applyUrl(s.getApplyUrl()).department(d).category(c).state(st).build());notifications.save(Notification.builder().title("New Job: "+j.getTitle()).body(j.getTitle()).job(j).type("NEW_JOB").build());return new Imported(j.getId());}catch(DataIntegrityViolationException e){return new Failed(e.getMostSpecificCause().getMessage());}catch(Exception e){return new Failed(e.getMessage());}}}
